# from triqs.gf import MeshReFreq, Gf, make_hermitian
from triqs.gf import *
import numpy as np
from itertools import product
from triqs.gf.descriptors import Fourier
from triqs.operators import c, c_dag
from triqs.gf.tools import inverse

# import of the abstract class
from solid_dmft.dmft_tools.solvers.abstractdmftsolver import AbstractDMFTSolver

# import triqs solver
from edipack2triqs.solver import EDIpackSolver
from edipack2triqs.fit import BathFittingParams

class EDInterface(AbstractDMFTSolver):
    def __init__(
        self, general_params, solver_params, sum_k, icrsh, h_int, iteration_offset, deg_orbs_ftps, gw_params=None, advanced_params=None
    ):
        # Call the base class constructor
        super().__init__(general_params, solver_params, sum_k, icrsh, h_int, iteration_offset, deg_orbs_ftps, gw_params, advanced_params)

        # # Create the ED solver specifics
        # self.bath_params = {}
        # keys_to_pass = ('bath_type', 'bath_sites', 'bath_mixing', 'bath_hybrid', 'bath_energy', 'fit_scheme', 'fit_method', 'fit_grad')
        # for key in keys_to_pass:
        #     self.bath_params[key] = self.solver_params[key]

        # Solver parameters for the EDIpack solver
        self.triqs_solver_params = {}
        keys_to_pass = ()
        for key in keys_to_pass:
            self.triqs_solver_params[key] = self.solver_params[key]
        

        # sets up necessary GF objects on ImFreq
        self._init_ImFreq_objects()

        # Define the bath Hamiltonian
        spins, orbs = ['up', 'dn'], range(len([orb[:-2] for orb in sum_k.block_structure.deg_shells[0] if orb.endswith('up')]))
        Nbath, Nspin, Norb = int(self.solver_params['bath_sites']), len(spins), len(orbs)
        
        eps = np.zeros((Norb, Norb, Nspin, Nspin, Nbath))
        V = np.zeros((Norb, Nspin, Nbath))
        eps_o = np.linspace(-float(self.solver_params['bath_energy']), float(self.solver_params['bath_energy']), Norb) 
        V_orb = np.linspace(-float(self.solver_params['bath_hybrid']), float(self.solver_params['bath_hybrid']), Norb)

        if self.solver_params['bath_type'] == 'replica':
            # eps is the tensor of the coefficients in the impurity Hamiltonian !!! MISSING !!!
            eps[:,:,:,:,:] = eps_o[-1]
            V[:,:,:] = V_orb[-1]
        elif self.solver_params['bath_type'] == 'hybrid':
            eps[:,:,:,:,:] = eps_o[-1]
            for b in range(Nbath):
                V[:,0,b], V[:,1,b] =  V_orb, V_orb
        else:
            eps[[0, 1], [0, 1], :] =  eps_o 
            for b in range(Nbath):
                V[:,0,b], V[:,1,b] =  V_orb, V_orb
                eps[:,:,0,0,b], eps[:,:,1,1,b] = np.diag(eps_o), np.diag(eps_o)

        H = sum(eps[o, op, s, sp, nu]
            * c_dag("B_" + s, o * Nbath + nu) * c("B_" + sp, op * Nbath + nu)
            for s, sp, o, op, nu in product(spins, spins, orbs, orbs, range(Nbath)))
        H += sum(V[o, s, nu] 
            * (c_dag(s, o) * c("B_" + s, o * Nbath + nu) + c_dag("B_" + s, o * Nbath + nu) * c(s, o))
            for s, o, nu in product(spins, orbs, range(Nbath)))
        
        H += h_int
        fops_imp_up, fops_imp_dn = [('up', o) for o in orbs], [('dn', o) for o in orbs]
        fops_bath_up, fops_bath_dn = [('B_up', i) for i in range(Norb * Nbath)], [('B_dn', i) for i in range(Norb * Nbath)]
        
        # Construct the triqs_solver instances
        fit_params = BathFittingParams(method=self.solver_params['fit_method'], grad=self.solver_params['fit_grad'])
        self.triqs_solver = EDIpackSolver(H, fops_imp_up, fops_imp_dn, fops_bath_up, fops_bath_dn,
                               lanc_dim_threshold=1024, verbose=1, bath_fitting_params=fit_params)

    def solve(self, **kwargs):
        # Solve the impurity problem for icrsh shell
        # *************************************
        # this is done on every node due to very slow bcast
        bath_old = self.triqs_solver.bath
        self.triqs_solver.solve(**self.triqs_solver_params)

        # call postprocessing
        self.postprocess(bath_old)

        return

    def postprocess(self, bath_old):
        r"""
        Organize G_freq, Sigma_freq and bath from hartree solver
        """

        self.G_freq_unsym << self.triqs_solver.g_iw
        self.sum_k.symm_deg_gf(self.G_freq, ish=self.icrsh)
        self.G_freq << self.triqs_solver.g_iw
        self.Sigma_freq << self.triqs_solver.Sigma_iw
        self.G0_freq << inverse(self.G_freq) + inverse(self.Sigma_freq)
        self.G_time << Fourier(self.G_freq)

        if self.solver_params['bath_mixing']:
            alpha = self.solver_params['bath_mixing']
        else:
            alpha = 1.0
        self.triqs_solver.bath = alpha * self.triqs_solver.chi2_fit_bath(self.G0_freq)[0] + (1 - alpha) * bath_old

        return